import re

from app.services import users

_SETTING_LINE = re.compile(r"([A-Za-z_][A-Za-z0-9_]*):(.*)")
_INTEGER = re.compile(r"-?[0-9]+")


def _parse_setting_value(raw: str) -> object:
    """Convert a raw setting value to its typed representation."""
    if len(raw) >= 2 and raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]
    if raw == "true":
        return True
    if raw == "false":
        return False
    if _INTEGER.fullmatch(raw):
        return int(raw)
    return raw


def handle_parse_settings(params: dict) -> tuple[int, dict]:
    text = params.get("text")
    if not isinstance(text, str):
        return 400, {"error": "invalid settings"}
    settings: dict[str, object] = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        match = _SETTING_LINE.fullmatch(line)
        if match is None:
            return 400, {"error": "invalid settings"}
        key = match.group(1)
        if key in settings:
            return 400, {"error": "invalid settings"}
        settings[key] = _parse_setting_value(match.group(2).strip())
    return 200, {"settings": settings}


